env:
  # Inputs are only set on workflow_dispatch; env overrides (used by the
  # local `act` test harness) take precedence, otherwise sensible defaults.
  REFERENCE_DATE: ${{ github.event.inputs.reference_date }}
  WARNING_WINDOW_DAYS: ${{ github.event.inputs.warning_window_days }}
  OUTPUT_FORMAT: ${{ github.event.inputs.output_format }}
run: |
  $ErrorActionPreference = 'Stop'

  # Resolve effective settings: explicit env (from act --env or dispatch
  # inputs) wins, otherwise fall back to deterministic defaults.
  $refDate = if ($env:REFERENCE_DATE) { $env:REFERENCE_DATE } else { (Get-Date -Format 'yyyy-MM-dd') }
  $window  = if ($env:WARNING_WINDOW_DAYS) { [int]$env:WARNING_WINDOW_DAYS } else { 14 }
  $format  = if ($env:OUTPUT_FORMAT) { $env:OUTPUT_FORMAT } else { 'markdown' }

